# -*- coding: utf-8 -*-
"""
Hand-authored specs for the most-used court papers.

Each spec describes only what differs between papers (facts, legal basis,
requests, extra fields). The composer in build_formulas_v2.py wraps them in the
common court-paper skeleton (opening block, «بناءً عليه», closing) exactly as
formula_204 (صحة التوقيع) is laid out.

Legal citations come from two places only:
  * the book «الكتاب الأول في الصيغ القانونية» (marked in `book`)
  * well-known statute articles written from standard practice (marked
    `needs_legal_review`) — a lawyer must confirm them before use.
"""

BOOK = 'الكتاب الأول في الصيغ القانونية — عدنان عبد المجيد والبسيوني محمود عبده'
PRACTICE = 'صياغة تحريرية وفق الأعراف الشائعة للمحاكم المصرية — تُراجَع من محامٍ قبل الاستخدام'

T = 'text'; D = 'date'; A = 'textarea'

def F(key, label, typ=T, hint=None, req=False):
    return (key, label, typ, hint, req)

SPECS = []
def spec(**kw):
    SPECS.append(kw)

# ═══════════════════════ الإيجارات والإخلاء (من الكتاب) ═══════════════════════
RENT = [F('contract_date', 'تاريخ عقد الإيجار', D, req=True),
        F('unit_desc', 'وصف العين المؤجرة', A, 'رقم الشقة/المحل ورقم العقار وعنوانه', True),
        F('monthly_rent', 'الأجرة الشهرية (جنيه)', T, req=True)]

spec(key='eviction_rent', replaces=['formula_225'], category='عرائض',
 title='صيغة دعوى إخلاء لعدم سداد الأجرة', subject='دعوى إخلاء لعدم سداد الأجرة', kind='lawsuit', nafaz=True,
 facts=('بموجب عقد إيجار مؤرخ {{contract_date}} استأجر المعلن إليه من الطالب {{unit_desc}} بأجرة شهرية قدرها {{monthly_rent}} جنيهًا. '
        'وقد تخلف المعلن إليه عن الوفاء بالأجرة عن المدة من {{arrears_from}} إلى {{arrears_to}}، وجملتها {{arrears_total}} جنيهًا. '
        'وبتاريخ {{warning_date}} كلّف الطالب المعلن إليه بالوفاء بهذه الأجرة بإعلان على يد محضر، ونبّه عليه بالوفاء بالأجرة المستحقة خلال {{warning_period}} من تاريخ التكليف وإلا اضطر لرفع دعوى الإخلاء، ورغم انقضاء هذا الأجل لم يقم بالوفاء.'),
 basis=['ولما كانت المادة 18 فقرة (ب) من القانون رقم 136 لسنة 1981 في شأن بعض الأحكام الخاصة بتأجير وبيع الأماكن وتنظيم العلاقة بين المؤجر والمستأجر تنص على أنه لا يجوز للمؤجر أن يطلب إخلاء المكان المؤجر ولو انتهت المدة المتفق عليها في العقد إلا لأحد الأسباب الآتية، ومنها: (ب) إذا لم يقم المستأجر بالوفاء بالأجرة المستحقة خلال خمسة عشر يومًا من تاريخ تكليفه بذلك بكتاب موصى عليه مصحوب بعلم الوصول دون مظروف أو بإعلان على يد محضر.',
        'ومن ثم يحق للطالب رفع دعوى الإخلاء الماثلة.'],
 requests='ليسمع الحكم بإخلائه من {{unit_short}} المبينة بصدر هذه الصحيفة وبعقد الإيجار المؤرخ {{contract_date}} وتسليمها للطالب خالية مما يشغلها',
 fields=RENT + [F('unit_short', 'العين باختصار', T, 'مثال: الشقة رقم 5 بالعقار رقم 12', True),
   F('arrears_from', 'بداية مدة التأخير', D), F('arrears_to', 'نهاية مدة التأخير', D),
   F('arrears_total', 'جملة المتأخر (جنيه)'), F('warning_date', 'تاريخ التكليف بالوفاء', D),
   F('warning_period', 'مهلة الوفاء الواردة بالتكليف', T, 'مثال: خمسة عشر يومًا')],
 source=(BOOK, 'دعوى اخلاء لعدم الوفاء بالاجرة المستحقة'))

